    private void InsW(
        string id, string name, string type, int value,
        int attack, int defense, int maxHp, int stock, string desc,
        int str, int end, int agi, int cun, int intel, int wis,
        int bonusPa, int bonusMa, int bonusDef, int bonusRes,
        int twoHanded, string dmgType, double atkSpdMod, string subtype,
        int dmgMin, int dmgMax, int atkRange, int requiredLevel)
    {
        Execute.Sql(FormattableString.Invariant(
            $"INSERT INTO items (id,name,type,value,attack,defense,max_health_bonus,heal_amount,restore_mana,stock,description,bonus_strength,bonus_endurance,bonus_agility,bonus_cunning,bonus_intellect,bonus_wisdom,bonus_phys_attack,bonus_mag_attack,bonus_defense,bonus_resistance,bonus_attack_speed,bonus_crit_chance,bonus_crit_damage,bonus_evade_chance,two_handed,damage_type,attack_speed_modifier,weapon_subtype,damage_min,damage_max,attack_range,required_level) VALUES ('{id}','{Esc(name)}','{type}',{value},{attack},{defense},{maxHp},0,0,{stock},'{Esc(desc)}',{str},{end},{agi},{cun},{intel},{wis},{bonusPa},{bonusMa},{bonusDef},{bonusRes},0.0,0.0,0.0,0.0,{twoHanded},'{dmgType}',{atkSpdMod},'{subtype}',{dmgMin},{dmgMax},{atkRange},{requiredLevel})"));
    }

    private static string Esc(string s) => s.Replace("'", "''");
